const $=s=>document.querySelector(s);const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cities={sh:'Shanghai',hz:'Hangzhou',cq:'Chongqing',jl:'Jilin',yt:'Yantai'};const centers={sh:[121.4737,31.2304],hz:[120.1551,30.2741],cq:[106.5516,29.563],jl:[126.5496,43.8379],yt:[121.4479,37.4638]};const types={0:'Residential',1:'Commercial',2:'Industrial',3:'Other'};const cls=t=>({0:'residential',1:'commercial',2:'industrial'}[Number(t)]||'other');const palette={residential:'#38bdf8',commercial:'#fb923c',industrial:'#4ade80',other:'#a78bfa'};
const state={rows:[],filtered:[],nodes:[],edges:[],selected:null,city:'sh',sample:60};
function teachingRows(city,count){const [cx,cy]=centers[city],rows=[];for(let i=0;i<count;i++){const a=i%12,d=(i*5+3)%12,ax=cx+((a%4)-1.5)*.018+Math.sin(i)*.0015,ay=cy+((a%3)-1)*.016+Math.cos(i)*.0012,dx=cx+((d%4)-1.5)*.018+Math.sin(i/2)*.0012,dy=cy+((d%3)-1)*.016+Math.cos(i/3)*.001;rows.push({package_id:`SAMPLE-${city}-${10000+i}`,courier_id:41+i%9,city:cities[city],aoi_id:100+i,aoi_type:i%4,accept_time:`2023-05-01 ${String(8+i%12).padStart(2,'0')}:${String((i*7)%60).padStart(2,'0')}:00`,delivery_time:`2023-05-01 ${String(9+i%11).padStart(2,'0')}:${String((i*9)%60).padStart(2,'0')}:00`,accept_gps_lng:ax,accept_gps_lat:ay,delivery_gps_lng:dx,delivery_gps_lat:dy,lng:dx,lat:dy,ds:20230501});}return rows;}
const normalize=x=>{const r=x?.row||x||{};return {...r,package_id:r.package_id??r.order_id,courier_id:r.courier_id,aoi_type:Number(r.aoi_type??3)};};const key=(x,y)=>`${Number(x).toFixed(3)},${Number(y).toFixed(3)}`;
function build(rows){const nodes=new Map(),edges=new Map();for(const r of rows){const ax=Number(r.accept_gps_lng),ay=Number(r.accept_gps_lat),dx=Number(r.delivery_gps_lng),dy=Number(r.delivery_gps_lat);if(![ax,ay,dx,dy].every(Number.isFinite))continue;const sk=key(ax,ay),dk=key(dx,dy),add=(k,lng,lat,delivery)=>{if(!nodes.has(k))nodes.set(k,{key:k,lng,lat,count:0,couriers:new Set(),types:{}});const n=nodes.get(k);if(delivery)n.count++;n.couriers.add(String(r.courier_id));n.types[r.aoi_type]=(n.types[r.aoi_type]||0)+1;};add(sk,ax,ay,false);add(dk,dx,dy,true);if(sk!==dk){const ek=sk+'|'+dk;if(!edges.has(ek))edges.set(ek,{source:sk,target:dk,count:0,couriers:new Set(),packages:new Set()});const e=edges.get(ek);e.count++;e.couriers.add(String(r.courier_id));e.packages.add(String(r.package_id));}}return{nodes:[...nodes.values()].map((n,i)=>{const type=Number(Object.entries(n.types).sort((a,b)=>b[1]-a[1])[0]?.[0]??3);return{...n,id:'L'+(i+1),type,size:Math.min(24,6+Math.sqrt(Math.max(1,n.count))*3)}}),edges:[...edges.values()]};}
function position(ns){if(!ns.length)return[];const xs=ns.map(n=>n.lng),ys=ns.map(n=>n.lat),minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys);return ns.map(n=>({...n,x:55+(n.lng-minX)/((maxX-minX)||1)*430,y:40+(maxY-n.lat)/((maxY-minY)||1)*500}));}
function draw(){const host=$('#network-viz');if(!host)return;const b=build(state.filtered);state.nodes=position(b.nodes);state.edges=b.edges;if(!state.nodes.length){host.innerHTML='<div class="empty-network"><strong>No records match the filters.</strong><span>Reset the filters or load another city.</span></div>';update();return;}const lookup=new Map(state.nodes.map(n=>[n.key,n]));let s='<svg viewBox="0 0 540 580" role="img" aria-label="Directed LaDe delivery network"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 z" fill="#78a8c6"/></marker></defs>';for(const e of state.edges){const a=lookup.get(e.source),b2=lookup.get(e.target);if(!a||!b2)continue;const active=state.selected&&[e.source,e.target].includes(state.selected.key);s+=`<line x1="${a.x}" y1="${a.y}" x2="${b2.x}" y2="${b2.y}" stroke="${active?'#4af4c5':'#6e9ab6'}" stroke-opacity="${active?.95:.6}" stroke-width="${Math.min(8,1+Math.sqrt(e.count))}" marker-end="url(#arrow)"/>`;}for(const n of state.nodes){const active=state.selected?.key===n.key;s+=`<g data-node="${esc(n.key)}" role="button" tabindex="0"><circle cx="${n.x}" cy="${n.y}" r="${n.size}" fill="${palette[cls(n.type)]}" stroke="${active?'#fff':'#09243a'}" stroke-width="${active?3:1.5}"/><text x="${n.x}" y="${n.y+n.size+14}" text-anchor="middle" fill="#c9e5f7" font-size="9">${esc(n.id)}</text></g>`;}s+='</svg>';host.innerHTML=s;host.querySelectorAll('[data-node]').forEach(el=>{const act=()=>{state.selected=state.nodes.find(n=>n.key===el.dataset.node)||null;draw();};el.onclick=act;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();act();}}});update();}
function update(){const rows=state.filtered;$('#metric-deliveries').textContent=rows.length.toLocaleString();$('#metric-couriers').textContent=new Set(rows.map(r=>r.courier_id)).size.toLocaleString();$('#metric-cells').textContent=state.nodes.length.toLocaleString();const h=Array(24).fill(0);rows.forEach(r=>{const m=String(r.delivery_time||'').match(/(?:T|\s)(\d{2}):/);if(m)h[Number(m[1])]++;});const mx=Math.max(1,...h);$('#hour-bars').innerHTML=h.map((v,i)=>`<div class="hour-bar" style="height:${Math.max(3,v/mx*76)}px"><span>${i%3===0?i:''}</span></div>`).join('');const d=$('#network-detail');if(!state.selected){d.innerHTML='<h3>Select a location</h3><p>Click a node to inspect activity and its strongest connections.</p>';}else{const n=state.selected,out=state.edges.filter(e=>e.source===n.key).sort((a,b)=>b.count-a.count),inc=state.edges.filter(e=>e.target===n.key);d.innerHTML=`<div class="selected-node"><span class="legend-dot ${cls(n.type)}"></span><strong>${esc(n.id)}</strong></div><p><strong>${n.count}</strong> delivery observations<br><strong>${n.couriers.size}</strong> couriers observed<br>AOI type: <strong>${esc(types[n.type])}</strong></p><div class="detail-label">Movement</div><p class="detail-value">${inc.reduce((q,e)=>q+e.count,0)} incoming · ${out.reduce((q,e)=>q+e.count,0)} outgoing trips</p><div class="detail-label">Top destinations</div><p class="detail-value">${out.slice(0,4).map(e=>`${esc(state.nodes.find(x=>x.key===e.target)?.id||'location')} · ${e.count} trips`).join('<br>')||'No outgoing connection in sample'}</p>`;}$('#edge-table').innerHTML='<table><thead><tr><th>Origin</th><th>Destination</th><th>Trips</th><th>Couriers</th></tr></thead><tbody>'+state.edges.sort((a,b)=>b.count-a.count).slice(0,40).map(e=>`<tr><td>${esc(state.nodes.find(n=>n.key===e.source)?.id||'—')}</td><td>${esc(state.nodes.find(n=>n.key===e.target)?.id||'—')}</td><td>${e.count}</td><td>${e.couriers.size}</td></tr>`).join('')+'</tbody></table>';}
async function load(){const city=$('#lade-city').value,limit=Math.max(20,Math.min(100,Number($('#lade-limit').value)||60));state.city=city;state.sample=limit;$('#lade-status').textContent='Loading LaDe-D…';try{const res=await fetch(`https://datasets-server.huggingface.co/rows?dataset=Cainiao-AI%2FLaDe-D&config=default&split=train&offset=0&length=${limit}`);if(!res.ok)throw Error();const json=await res.json();const all=(json.rows||[]).map(normalize),cityRows=all.filter(r=>String(r.city||'').toLowerCase()===cities[city].toLowerCase());state.rows=cityRows.length?cityRows:teachingRows(city,limit);$('#lade-status').textContent=cityRows.length?`LaDe-D · ${cityRows.length} rows loaded`:'Teaching sample · no rows for this city in the loaded slice';}catch{state.rows=teachingRows(city,limit);$('#lade-status').textContent='Teaching sample · live viewer unavailable';}apply();}
function apply(){let r=[...state.rows],t=$('#aoi-filter').value,p=$('#package-filter').value.trim().toLowerCase(),date=$('#lade-date').value;if(t!=='all')r=r.filter(x=>String(x.aoi_type)===t);if(p)r=r.filter(x=>String(x.package_id).toLowerCase().includes(p));if(date)r=r.filter(x=>String(x.delivery_time||'').slice(0,10)===date||String(x.ds)===date.replaceAll('-',''));state.filtered=r;state.selected=null;const ts=[...new Set(r.map(x=>String(x.aoi_type)))].sort();$('#aoi-filter').innerHTML='<option value="all">All types</option>'+ts.map(x=>`<option value="${x}">${esc(types[x]||'Other')}</option>`).join('');draw();}
$('#lade-refresh').onclick=load;$('#lade-city').onchange=load;$('#lade-limit').onchange=load;$('#lade-date').onchange=apply;$('#aoi-filter').onchange=apply;$('#package-filter').oninput=apply;$('#lade-reset').onclick=()=>{$('#package-filter').value='';$('#lade-date').value='';apply();};load();
